# rubik_solve_asm: optimal 2x2x2 cube solver, hand-written RV32I.
#
# int rubik_solve_asm(const char *state, char *out, size_t cap)
#                                   a0 = state, a1 = out, a2 = cap; result in a0
#
# RV32I and Zicsr only: no mul, div, rem, no floating point, no compressed
# instructions, no heap, no recursion. Tests: tests/trubik.c.

.include "src/rubik/tables.inc"

# GENERATED by tools/gen_asm_data.c - do not edit.
.equ PDB_ENTRIES, 68040
.equ PDB_BYTES, 34020
# tracked cubies (internal ids 0..6): set A and set B
.equ A0, 0
.equ A1, 1
.equ A2, 3
.equ A3, 4
.equ B0, 2
.equ B1, 4
.equ B2, 5
.equ B3, 6
# byte sums, for the M1 data-loading milestone
.equ SUM_QT, 9234
.equ SUM_A, 3643227
.equ SUM_B, 3643512

# characters for output

.equ O_R, 82

.equ O_B, 66

.equ O_D, 68

.equ O_2, 50

.equ O_I, 39 # '\\''

.equ O_S, 32 # ' '

.data



move_face: .byte 0, 0, 0, 1, 1, 1, 2, 2, 2

move_turn: .byte 0, 1, 2, 0, 1, 2, 0, 1, 2

.bss

st:

    .zero  104



last_face:

    .zero  12



next_move:

    .zero  12



taken:

    .zero  12

    .text

    .globl  rubik_solve_asm
    .type   rubik_solve_asm, @function
    .align  2
rubik_solve_asm:
    addi    sp, sp, -64

    sw      s0, 0(sp)
    sw      s1, 4(sp)
    sw      s2, 8(sp)
    sw      s3, 12(sp)
    sw      s4, 16(sp)
    sw      s5, 20(sp)
    sw      s6, 24(sp)
    sw      s7, 28(sp)
    sw      s8, 32(sp)
    sw      s9, 36(sp)
    sw      s10, 40(sp)
    sw      s11, 44(sp)

    sw      a1, 48(sp)       # 原始 out
    sw      a2, 52(sp)       # 原始 cap
    sw      ra, 56(sp)
    sw      a0, 60(sp)       # 原始 state

#------------------------------------------------------------

# Register allocation in search

#

# s0 = st base

# s1 = QT base

# s2 = PDB_A base

# s3 = PDB_B base

#

# a1 = last_face base

# a2 = next_move base

# a3 = move_face base

# a4 = move_turn base

# a5 = taken base

#

# t0 = bound

# t1 = number of moves (9)

# t2 = d

# t3 = m

# t4 = f

# t5  = scratch

# t6 = g

#

# a7 = saved ha, during lazy heuristic

#

# h_a / h_b are directly inlined in the initial bound and DFS:

#   input a0 = state pointer

#   output a6 = heuristic

#   preserve t0-t4, t6, a1-a5, a7, s0-s3

#   clobber t5, s4-s11, a6

#

# IMPORTANT: inline heuristic modifies s4-s11 and a6; preserves a7.
# No heuristic call/ret executes on the DFS hot path.

#------------------------------------------------------------



    # Initialize all long-lived bases BEFORE heuristics.

    la s0, st

    la s1, QT

    la s2, PDB_A

    la s3, PDB_B



    la a1, last_face

    la a2, next_move

    la a3, move_face

    la a4, move_turn

    la a5, taken



    # --------------------------------------------------------

    # parse input

    #

    # input:

    #   first 7 chars  = cubie IDs '1'..'7'

    #   second 7 chars = orientations '1'..'3'

    #

    # st[0][c] = (i << 2) | orientation

    # --------------------------------------------------------



    lw      t0, 60(sp)       # 呼叫者傳入的 state
    li      t1, 14

# unroll?
check_state_length:
    lbu     t2, 0(t0)
    beqz    t2, SOLVE_E_INPUT
    addi    t0, t0, 1
    addi    t1, t1, -1
    bnez    t1, check_state_length

    # NUL
    lbu     t2, 0(t0)
    bnez    t2, SOLVE_E_INPUT

    # back to the start of state parse_loop
    lw      t0, 60(sp)       # position characters
    addi    t1, t0, 7        # orientation characters



    li t2, 0             # i

    li t3, 0             # seen mask

    li t4, 0             # orientation sum



parse_loop:

    lbu t5, 0(t0)        # position character

    lbu t6, 0(t1)        # orientation character



    addi t5, t5, -49     # c = char - '1'

    li a6, 7

    bgeu t5, a6, SOLVE_E_INPUT



    addi t6, t6, -49     # o = char - '1'

    li a6, 3

    bgeu t6, a6, SOLVE_E_INPUT



    # Duplicate cubie check

    li a6, 1

    sll a6, a6, t5



    and a0, a6, t3

    bnez a0, SOLVE_E_INPUT



    or t3, t3, a6



    # sum += o

    add t4, t4, t6



    # encoded = (i << 2) | o

    slli a6, t2, 2

    or a6, a6, t6



    # st[0][c] = encoded

    # uint8_t => offset is c

    add a0, s0, t5

    sb a6, 0(a0)



    # next input character

    addi t0, t0, 1

    addi t1, t1, 1

    addi t2, t2, 1



    li a6, 7

    bltu t2, a6, parse_loop



    # sum % 3

    li a6, 3



parse_mod:

    bltu t4, a6, parse_mod_done

    addi t4, t4, -3

    j parse_mod



parse_mod_done:

    bnez t4, SOLVE_E_INPUT

    lw      t5, 52(sp)
    beqz    t5, output_too_small

    # --------------------------------------------------------

    # Initial heuristic h0 = max(hA, hB)

    # --------------------------------------------------------



    # mv a0, s0

    # ---- BEGIN INLINE h_a (s0 -> a6) ----
    lbu s4, A0(s0)
    lbu s5, A1(s0)
    lbu s6, A2(s0)
    lbu s7, A3(s0)
    andi s8, s4, 3
    slli s9, s8, 1
    add s8, s8, s9
    andi s9, s5, 3
    add s8, s8, s9
    slli s9, s8, 1
    add s8, s8, s9
    andi s9, s6, 3
    add s8, s8, s9
    slli s9, s8, 1
    add s8, s8, s9
    andi s9, s7, 3
    add s8, s8, s9 # o
    srli s4, s4, 2
    srli s5, s5, 2
    srli s6, s6, 2
    srli a0, s7, 2 # A3 = B1
    sltu s9, s4, s5
    sub s9, s5, s9
    sltu s11, s4, s6
    sub s10, s6, s11
    sltu s11, s5, s6
    sub s10, s10, s11
    sltu a6, s4, a0
    sub s11, a0, a6
    sltu a6, s5, a0
    sub s11, s11, a6
    sltu a6, s6, a0
    sub s11, s11, a6
    slli a6, s4, 2
    add s9, s9, a6
    slli a6, s4, 1
    add s9, s9, a6
    slli a6, s9, 2
    add s9, s9, a6
    add s9, s9, s10
    slli s9, s9, 2
    add s9, s9, s11
    slli a6, s9, 6
    add s8, s8, a6
    slli a6, s9, 4
    add s8, s8, a6
    add s8, s8, s9
    srli s9, s8, 1
    add s9, s2, s9
    lbu s9, 0(s9)
    andi s10, s8, 1
    slli s10, s10, 2
    srl s9, s9, s10
    andi t0, s9, 15
    # ---- END INLINE h_a ----



    # mv t0, a6            # t0 = ha



    # s0 still points to st[0]

    # ---- BEGIN INLINE h_b (s0 -> a6) ----
    lbu s4, B0(s0)
    # lbu s5, B1(s0)
    lbu s6, B2(s0)
    lbu s5, B3(s0)
    andi s8, s4, 3
    slli s9, s8, 1
    add s8, s8, s9
    andi s9, s7, 3 # B1
    add s8, s8, s9
    slli s9, s8, 1
    add s8, s8, s9
    andi s9, s6, 3
    add s8, s8, s9
    slli s9, s8, 1
    add s8, s8, s9
    andi s9, s5, 3
    add s8, s8, s9
    srli s4, s4, 2
    # srli s5, s5, 2
    srli s6, s6, 2
    srli s5, s5, 2
    sltu s9, s4, a0
    sub s9, a0, s9
    sltu s11, s4, s6
    sub s10, s6, s11
    sltu s11, a0, s6
    sub s10, s10, s11
    sltu a6, s4, s5
    sub s11, s5, a6
    sltu a6, a0, s5
    sub s11, s11, a6
    sltu a6, s6, s5
    sub s11, s11, a6
    slli a6, s4, 2
    add s9, s9, a6
    slli a6, s4, 1
    add s9, s9, a6
    slli a6, s9, 2
    add s9, s9, a6
    add s9, s9, s10
    slli s9, s9, 2
    add s9, s9, s11
    slli a6, s9, 6
    add s8, s8, a6
    slli a6, s9, 4
    add s8, s8, a6
    add s8, s8, s9
    srli s9, s8, 1
    add s9, s3, s9
    lbu s9, 0(s9)
    andi s10, s8, 1
    slli s10, s10, 2
    srl s9, s9, s10
    andi a6, s9, 15
    # ---- END INLINE h_b ----



    # t0 = max(ha, hb)

    bgeu t0, a6, initial_h_done

    mv t0, a6



initial_h_done:

    # Initial state is already solved

    beqz t0, solved_initial



    # t1 = number of moves

    li t1, 9



#------------------------------------------------------------

# IDA* outer loop

#

# for (bound = h0; bound <= 11; bound++)

#------------------------------------------------------------



boundloop:

    li t5, 12
    bgeu t0, t5, SOLVE_E_BOUND



    li t2, 0             # d = 0



    # last_face[0] = 3 (no previous face)

    li t5, 3

    sb t5, 0(a1)



    # next_move[0] = 0

    sb zero, 0(a2)



#------------------------------------------------------------

# Explicit DFS

#------------------------------------------------------------



dfsloop:

    # m = next_move[d]

    add t5, a2, t2

    lbu t3, 0(t5)



    # Check m before accessing move_face[m]

    bgeu t3, t1, exhausted



    # face = move_face[m]

    add t5, a3, t3

    lbu t4, 0(t5)



    # previous face = last_face[d]

    add t6, a1, t2

    lbu t6, 0(t6)



    # if same face, m += 3

    bne t4, t6, unexhausted

    addi t3, t3, 3

    # f = move_face[m]

    bgeu t3, t1, exhausted

    lbu t4, 3(t5)



unexhausted:


    j move



exhausted:

    # All moves at this depth have been tried.

    # If root is exhausted, increase IDA* bound.

    beqz t2, bound_next



    # Backtrack one level

    addi t2, t2, -1

    j dfsloop



bound_next:

    addi t0, t0, 1

    j boundloop



#------------------------------------------------------------

# Generate child

#------------------------------------------------------------



move:

    # next_move[d] = m + 1

    add t5, a2, t2

    addi a6, t3, 1

    sb a6, 0(t5)



    # dst = &st[d+1][0]

    addi t5, t2, 1

    slli t5, t5, 3

    add t5, s0, t5



    # Default src = dst

    mv t6, t5



    # move_turn[m]

    add a6, a4, t3

    lbu a6, 0(a6)



    # If move_turn[m] != 0, reuse previous child.

    bnez a6, turn_begin



    # Otherwise src = &st[d][0]

    addi t6, t5, -8



turn_begin:

    # s1 = QT base
    # t4 = face
    # t5 = dst
    # t6 = src

    # QT + face*32

    slli a7, t4, 5

    add a7, s1, a7

    # turn(dst, src, face)

    # Seven independent byte transformations.


    # s4 = st[d+1][0]
    
    lbu s4, 0(t6)

    add s4, a7, s4

    lbu s4, 0(s4)

    sb s4, 0(t5)


    # s5 = st[d+1][1]

    lbu s5, 1(t6)

    add s5, a7, s5

    lbu s5, 0(s5)

    sb s5, 1(t5)


    # s6 = st[d+1][3]

    lbu s6, 3(t6)

    add s6, a7, s6

    lbu s6, 0(s6)

    sb s6, 3(t5)


    # s7 = st[d+1][4]

    lbu s7, 4(t6)

    add s7, a7, s7

    lbu s7, 0(s7)

    sb s7, 4(t5)


    # h_a(child)

    # ---- BEGIN INLINE h_a (-> a6) ----
    andi s8, s4, 3
    slli s9, s8, 1
    add s8, s8, s9
    andi s9, s5, 3
    add s8, s8, s9
    slli s9, s8, 1
    add s8, s8, s9
    andi s9, s6, 3
    add s8, s8, s9
    slli s9, s8, 1
    add s8, s8, s9
    andi s9, s7, 3
    add s8, s8, s9
    srli s4, s4, 2
    srli s5, s5, 2
    srli s6, s6, 2
    srli a0, s7, 2
    sltu s9, s4, s5
    sub s9, s5, s9
    sltu s11, s4, s6
    sub s10, s6, s11
    sltu s11, s5, s6
    sub s10, s10, s11
    sltu a6, s4, a0
    sub s11, a0, a6
    sltu a6, s5, a0
    sub s11, s11, a6
    sltu a6, s6, a0
    sub s11, s11, a6
    slli a6, s4, 2
    add s9, s9, a6
    slli a6, s4, 1
    add s9, s9, a6
    slli a6, s9, 2
    add s9, s9, a6
    add s9, s9, s10
    slli s9, s9, 2
    add s9, s9, s11
    slli a6, s9, 6
    add s8, s8, a6
    slli a6, s9, 4
    add s8, s8, a6
    add s8, s8, s9
    srli s9, s8, 1
    add s9, s2, s9
    lbu s9, 0(s9)
    andi s10, s8, 1
    slli s10, s10, 2
    srl s9, s9, s10
    andi a6, s9, 15
    # ---- END INLINE h_a ----



    # turn(dst, src, face)

    # s4 = st[d+1][2]

    lbu s4, 2(t6)

    add s4, a7, s4

    lbu s4, 0(s4)

    sb s4, 2(t5)


    # s6 = st[d+1][5]

    lbu s6, 5(t6)

    add s6, a7, s6

    lbu s6, 0(s6)

    sb s6, 5(t5)


    # s5 = st[d+1][6]

    lbu s5, 6(t6)

    add s5, a7, s5

    lbu s5, 0(s5)

    sb s5, 6(t5)


    # --------------------------------------------------------

    # Lazy PDB evaluation

    #

    # g = d + 1

    # --------------------------------------------------------


    # t6 = g

    addi t6, t2, 1


    # if (g + ha > bound) continue

    add s8, t6, a6

    bltu t0, s8, dfsloop



    # h_b(child)

    # ---- BEGIN INLINE h_b (-> a7) ----
    andi s8, s4, 3
    slli s9, s8, 1
    add s8, s8, s9
    andi s9, s7, 3
    add s8, s8, s9
    slli s9, s8, 1
    add s8, s8, s9
    andi s9, s6, 3
    add s8, s8, s9
    slli s9, s8, 1
    add s8, s8, s9
    andi s9, s5, 3
    add s8, s8, s9
    srli s4, s4, 2
    srli s6, s6, 2
    srli s5, s5, 2
    sltu s9, s4, a0
    sub s9, a0, s9
    sltu s11, s4, s6
    sub s10, s6, s11
    sltu s11, a0, s6
    sub s10, s10, s11
    sltu a7, s4, s5
    sub s11, s5, a7
    sltu a7, a0, s5
    sub s11, s11, a7
    sltu a7, s6, s5
    sub s11, s11, a7
    slli a7, s4, 2
    add s9, s9, a7
    slli a7, s4, 1
    add s9, s9, a7
    slli a7, s9, 2
    add s9, s9, a7
    add s9, s9, s10
    slli s9, s9, 2
    add s9, s9, s11
    slli a7, s9, 6
    add s8, s8, a7
    slli a7, s9, 4
    add s8, s8, a7
    add s8, s8, s9
    srli s9, s8, 1
    add s9, s3, s9
    lbu s9, 0(s9)
    andi s10, s8, 1
    slli s10, s10, 2
    srl s9, s9, s10
    andi a7, s9, 15
    # ---- END INLINE h_b ----



    # if (g + hb > bound) continue

    add t5, t6, a7

    bltu t0, t5, dfsloop



    # if ((ha | hb) == 0) found

    or t5, a6, a7

    beqz t5, found



    # --------------------------------------------------------

    # Descend

    # --------------------------------------------------------



    # taken[d] = m

    add t5, a5, t2

    sb t3, 0(t5)



    # last_face[d+1] = f

    add t5, a1, t2

    sb t4, 1(t5)



    # next_move[d+1] = 0

    add t5, a2, t2

    sb zero, 1(t5)



    # d++

    addi t2, t2, 1

    j dfsloop



#------------------------------------------------------------

# Found solution

#

# taken[0..d-1] are previous moves.

# t3 is the final move.
# a1 is length of needed output space

#

# Print directly; do not create path[].

#------------------------------------------------------------



found:
    # The last move is not yet stored in taken[d].
    # Record it now, then replay the ACTUAL emitted path.
    add t5, a5, t2
    sb t3, 0(t5)
    addi t6, t2, 1           # path length
    li t2, 0                 # i taken index

    # a1 = needed
    li a1, 1

    li s6, 3
    li s7, 6
    li s8, 1
    li s9, 2

name_length_loop:
    slt a3, zero, t2
    add a1, a1, a3
    # a3 = taken[i]
    add a3, a5, t2
    lbu a3, 0(a3)
    beqz a3, name_length_one    # taken == 0
    beq a3, s6, name_length_one # taken == 3
    beq a3, s7, name_length_one # taken == 6
    addi a1, a1, 1

name_length_one:
    addi t2, t2, 1
    addi a1, a1, 1
    bltu t2, t6, name_length_loop

    # cap < needed
    lw a0, 52(sp) # a0 = cap
    bltu a0, a1, output_too_small_nonzero

    # t0 = out pointer
    lw t0, 48(sp)

    li s0, O_R
    li s1, O_B
    li s2, O_D
    li s3, O_2
    li s4, O_I
    li s5, O_S

    li t2, 0                 # i taken index

found_loop:
    bgeu t2, t6, found_done
    beqz t2, skip_space
    # *p++ = ' '
    sb s5, 0(t0)
    addi t0, t0, 1
skip_space:
    add t5, a5, t2
    lbu a6, 0(t5)             # one actual solution move

    # a0 = suffix
    bltu a6, s6, place_R

    bltu a6, s7, place_B

    # place_D
    sb s2, 0(t0)
    addi t0, t0, 1
    sub a6, a6, s7
    j place_suffix

place_R:
    sb s0, 0(t0)
    addi t0, t0, 1
    j place_suffix

place_B:
    sb s1, 0(t0)
    addi t0, t0, 1
    sub a6, a6, s6

place_suffix:
    beq a6, s8, place_two

    bne a6, s9, place_suffix_end

    # place prime
    sb s4, 0(t0)
    addi t0, t0, 1
    j place_suffix_end

place_two:
    sb s3, 0(t0)
    addi t0, t0, 1

place_suffix_end:
    addi t2, t2, 1
    j found_loop

found_done:
    sb zero, 0(t0)
    mv a0, t6

    j rubik_return

solved_initial:

    # Empty solution

    lw      t5, 48(sp)
    sb      zero, 0(t5)
    li      a0, 0
    j       rubik_return



#------------------------------------------------------------

# Exit

#------------------------------------------------------------


SOLVE_E_INPUT:

    li      a0, -1
    j       rubik_return


output_too_small:
    lw      t5, 52(sp)
    beqz    t5, return_capacity_error

output_too_small_nonzero:
    lw      t5, 48(sp)
    sb      zero, 0(t5)

return_capacity_error:
    li      a0, -2
    j       rubik_return

SOLVE_E_BOUND:
    li a0, -3

rubik_return:
    lw      s0, 0(sp)
    lw      s1, 4(sp)
    lw      s2, 8(sp)
    lw      s3, 12(sp)
    lw      s4, 16(sp)
    lw      s5, 20(sp)
    lw      s6, 24(sp)
    lw      s7, 28(sp)
    lw      s8, 32(sp)
    lw      s9, 36(sp)
    lw      s10, 40(sp)
    lw      s11, 44(sp)
    lw      ra, 56(sp)

    addi    sp, sp, 64
    ret
    .size   rubik_solve_asm, .-rubik_solve_asm
